{
  "lines": [
    {
      "key": "opening",
      "japanese": "あれ、〇〇ちゃん？",
      "reading": "あれ、まるまるちゃん？",
      "romaji": "Are, marumaru-chan? \nWhat are you doing here, [Name]-chan? \n(A recognizes B, using a familiar suffix -chan, implying they know each other well. The 'Are' expresses mild surprise.)"
    },
    {
      "key": "reply",
      "japanese": "あ、〇〇！うん、ちょっとプレゼントを探してて。",
      "reading": "あ、まるまる！うん、ちょっとプレゼントをさがしてて。",
      "romaji": "A, marumaru! \nUn, chotto purezento o sagashite te.\nOh, [Name]! Yeah, I'm just looking for a present."
    },
    {
      "key": "follow_up",
      "japanese": "へえ、誰かに？",
      "reading": "へえ、だれかに？",
      "romaji": "He~, dareka ni?\nOh, for someone?"
    },
    {
      "key": "explanation",
      "japanese": "うん、友達の誕生日なんだ。",
      "reading": "うん、ともだちのたんじょうびなんだ。",
      "romaji": "Un, tomodachi no tanjoubi nan da.\nYeah, it's my friend's birthday."
    }
  ]
}

